static const char WEB_INDEX_HTML[] = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Macro</title>\n<link rel=\"icon\" href=\"data:,\">\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/ace/1.36.5/ace.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/ace/1.36.5/mode-json.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/ace/1.36.5/theme/tomorrow_night.min.js\"></script>\n</head>\n<body class=\"bg-zinc-900 text-zinc-100 antialiased min-h-screen\">\n<main class=\"max-w-2xl mx-auto p-4 space-y-4\">\n  <header class=\"flex items-center justify-between gap-2\">\n    <h1 class=\"text-lg font-semibold\">MacroPassthrough</h1>\n    <a href=\"/docs/profile-schema\" class=\"text-sm text-blue-400 hover:underline\">Schema docs</a>\n  </header>\n\n  <div class=\"flex flex-wrap gap-2\">\n    <button type=\"button\" id=\"btn-toggle\" class=\"px-4 py-2 rounded-md text-sm font-medium text-white bg-zinc-600\">Macros OFF</button>\n    <button type=\"button\" id=\"btn-reload\" class=\"px-4 py-2 rounded-md text-sm bg-zinc-700 hover:bg-zinc-600\">Reload</button>\n    <button type=\"button\" id=\"btn-upload\" class=\"px-4 py-2 rounded-md text-sm bg-blue-600 hover:bg-blue-500 text-white\">Upload</button>\n  </div>\n\n  <section class=\"text-sm space-y-1 border border-zinc-700 rounded-lg p-3 bg-zinc-800/50\">\n    <p><span class=\"text-zinc-500\">Macro:</span> <span id=\"v-profile\" class=\"font-medium\">—</span></p>\n    <p><span class=\"text-zinc-500\">Gun:</span> <span id=\"v-gun\" class=\"font-medium\">—</span></p>\n    <p><span class=\"text-zinc-500\">Script:</span> <span id=\"v-script\" class=\"font-medium\">—</span></p>\n    <p><span class=\"text-zinc-500\">Status:</span> <span id=\"v-status\">—</span></p>\n    <p id=\"v-conn\" class=\"text-xs text-zinc-500 pt-1\">Connecting…</p>\n  </section>\n\n  <div id=\"profile-json\" class=\"w-full h-72 rounded-md border border-zinc-700 overflow-hidden\"></div>\n  <p id=\"msg\" class=\"text-xs text-zinc-500\"></p>\n</main>\n<script>\n(function () {\n  var q = Promise.resolve(), ab = null;\n  var editor = ace.edit('profile-json');\n  editor.setTheme('ace/theme/tomorrow_night');\n  editor.session.setMode('ace/mode/json');\n  editor.session.setUseWorker(false);\n  editor.setOptions({ fontSize: 12, showPrintMargin: false, tabSize: 2, useSoftTabs: true });\n  function $(id) { return document.getElementById(id); }\n  function pad(n) { return '  '.repeat(n); }\n  function formatValue(val, indent) {\n    if (val === null) return 'null';\n    if (typeof val !== 'object') return JSON.stringify(val);\n    if (Array.isArray(val)) {\n      if (!val.length) return '[]';\n      return '[\\n' + val.map(function (item) {\n        return pad(indent + 1) + formatValue(item, indent + 1);\n      }).join(',\\n') + '\\n' + pad(indent) + ']';\n    }\n    var keys = Object.keys(val);\n    if (!keys.length) return '{}';\n    var lines = keys.map(function (k) {\n      var v = val[k];\n      if (k === 'steps' && Array.isArray(v)) {\n        var steps = v.map(function (s) { return pad(indent + 1) + JSON.stringify(s); });\n        return pad(indent + 1) + '\"steps\": [\\n' + steps.join(',\\n') + '\\n' + pad(indent + 1) + ']';\n      }\n      return pad(indent + 1) + JSON.stringify(k) + ': ' + formatValue(v, indent + 1);\n    });\n    return '{\\n' + lines.join(',\\n') + '\\n' + pad(indent) + '}';\n  }\n  function setJson(t) {\n    try { editor.setValue(formatValue(JSON.parse(t), 0), -1); }\n    catch (e) { editor.setValue(t, -1); }\n  }\n  function getJson() { return editor.getValue(); }\n  function fetchQ(url, opts) {\n    opts = opts || {};\n    function go() {\n      if (ab) ab.abort();\n      ab = new AbortController();\n      var t = setTimeout(function () { ab.abort(); }, 12000);\n      var init = { cache: 'no-store', signal: ab.signal };\n      if (opts.method) init.method = opts.method;\n      if (opts.body != null) init.body = opts.body;\n      if (opts.headers) init.headers = opts.headers;\n      return fetch(url, init).finally(function () { clearTimeout(t); ab = null; });\n    }\n    var p = q.then(go, go);\n    q = p.catch(function () {});\n    return p;\n  }\n  function setToggle(on) {\n    var b = $('btn-toggle');\n    b.textContent = on ? 'Macros ON' : 'Macros OFF';\n    b.className = on\n      ? 'px-4 py-2 rounded-md text-sm font-medium text-white bg-green-600 hover:bg-green-500'\n      : 'px-4 py-2 rounded-md text-sm font-medium text-white bg-zinc-600 hover:bg-zinc-500';\n    var s = $('v-status');\n    s.textContent = on ? 'Macros enabled' : 'Macros disabled';\n    s.className = on ? 'text-green-400 font-medium' : 'text-red-400 font-medium';\n  }\n  function applyStatus(j) {\n    $('v-profile').textContent = j.profile || '—';\n    $('v-gun').textContent = j.activeWeaponName || '—';\n    $('v-script').textContent = j.activeScriptName || '—';\n    setToggle(!!j.macrosOn);\n  }\n  function setConn(ok, txt) {\n    $('v-conn').textContent = txt;\n    $('v-conn').className = ok ? 'text-xs text-green-400 pt-1' : 'text-xs text-amber-400 pt-1';\n  }\n  function setMsg(txt, ok) {\n    $('msg').textContent = txt || '';\n    $('msg').className = ok ? 'text-xs text-green-400' : (txt ? 'text-xs text-amber-400' : 'text-xs text-zinc-500');\n  }\n  function refresh() {\n    setConn(false, 'Loading…');\n    return fetchQ('/api/ping')\n      .then(function (r) { if (!r.ok) throw 0; return fetchQ('/api/status'); })\n      .then(function (r) { if (!r.ok) throw 0; return r.json(); })\n      .then(function (j) { applyStatus(j); setConn(true, 'Connected'); })\n      .catch(function () { setConn(false, 'Offline — use Reload'); });\n  }\n  function loadProfile() {\n    return fetchQ('/api/profile')\n      .then(function (r) { if (!r.ok) throw 0; return r.text(); })\n      .then(setJson)\n      .catch(function () { setMsg('Could not load profile JSON.', false); });\n  }\n  function boot() {\n    return refresh().then(loadProfile).then(function () { setMsg('', false); });\n  }\n  $('btn-toggle').onclick = function () {\n    fetchQ('/api/toggle-macros', { method: 'POST' })\n      .then(function (r) { if (!r.ok) throw 0; return refresh(); })\n      .catch(function () { setMsg('Toggle failed.', false); });\n  };\n  $('btn-reload').onclick = boot;\n  $('btn-upload').onclick = function () {\n    var t = getJson();\n    try { JSON.parse(t); } catch (e) { setMsg('Invalid JSON.', false); return; }\n    setMsg('Uploading…', false);\n    fetchQ('/api/profile', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: t })\n      .then(function (r) { if (!r.ok) throw 0; return boot(); })\n      .then(function () { setMsg('Uploaded.', true); })\n      .catch(function () { setMsg('Upload failed.', false); });\n  };\n  setTimeout(boot, 400);\n})();\n</script>\n</body>\n</html>\n";
